// When the program started (its first own code), for the log: the boot before the loading screen.
extern "C" unsigned long long nx_start_tick = 0;

// libnx's hooks around main(): the file system is up here.
extern "C" void userAppInit() {
    nx_start_tick = armGetSystemTick();
    mkdir("sdmc:/switch", 0777);
    mkdir(kRoot, 0777);
    mkdir(kLocal, 0777);
    // The GL driver's shader cache in our folder (its default, sdmc:/config/ouncevk, is refused by
    // the guard). Read when EGL starts, so before that.
    setenv("MESA_SHADER_CACHE_DIR", "sdmc:/switch/warsmash/ouncevk", 0);
    // Java's System.out/err (Clearwing: stdout/stderr) into the log, a line at a time. stderr was
    // unbuffered, so each System.err.println was several SD-card writes (2026-11-22: thousands of
    // warnings a minute in OrcX01); a line at a time keeps the crash tail and costs one write.
    if (freopen(kLog, "w", stdout))
        setvbuf(stdout, nullptr, _IOLBF, 0);
    if (freopen(kLog, "a", stderr))
        setvbuf(stderr, nullptr, _IOLBF, 0);
    ws_switch2_crash_paths(kCrash, kLog);
    printf("warsmash-nx: log started\n");
}

extern "C" void userAppExit() {
    // The loading CPU boost (NxLoadingScreen.setLoadingBoost) off, in case the game quit mid-load:
    // hbloader and hbmenu run on in this process afterwards. As the Torchlight port's userAppExit.
    (void) appletSetCpuBoostMode(ApmCpuBoostMode_Normal);
    fflush(stdout);
}

void *getBufferAddress(jcontext ctx, java_nio_Buffer *buffer) {
    if (!buffer)
        return nullptr;
    int typeSize = 1;
    if (isInstance(ctx, (jobject) buffer, &class_java_nio_ByteBuffer))
        typeSize = sizeof(jbyte);
    else if (isInstance(ctx, (jobject) buffer, &class_java_nio_FloatBuffer))
        typeSize = sizeof(jfloat);
    else if (isInstance(ctx, (jobject) buffer, &class_java_nio_IntBuffer))
        typeSize = sizeof(jint);
    else if (isInstance(ctx, (jobject) buffer, &class_java_nio_ShortBuffer))
        typeSize = sizeof(jshort);
    else if (isInstance(ctx, (jobject) buffer, &class_java_nio_CharBuffer))
        typeSize = sizeof(jchar);
    else if (isInstance(ctx, (jobject) buffer, &class_java_nio_LongBuffer))
        typeSize = sizeof(jlong);
    else if (isInstance(ctx, (jobject) buffer, &class_java_nio_DoubleBuffer))
        typeSize = sizeof(jdouble);
    return (char*)buffer->F_address + typeSize * buffer->F_position;
}

void *getBufferAddress(java_nio_ByteBuffer *buffer) {
    return (char*)buffer->parent.F_address + sizeof(jbyte) * buffer->parent.F_position;
}

void *getBufferAddress(java_nio_ShortBuffer *buffer) {
    return (char*)buffer->parent.F_address + sizeof(jshort) * buffer->parent.F_position;
}

