// warsmash-nx: the loading screen (wsnx.warsmash.NxLoadingScreen) presents its own frames while the game is
// still inside create(), before SwitchApplication's loop runs update(). It answers what update()
// would meanwhile: + and - held together, and the system asking the app to close.
void nx_present_loading_frame() {
    padUpdate(&combinedPad);
    const u64 held = padGetButtons(&combinedPad);
    const bool quit = (held & HidNpadButton_Plus) && (held & HidNpadButton_Minus);
    if (quit || !appletMainLoop()) {
        printf("warsmash-nx: quit while loading\n");
        fflush(stdout);
        SM_com_thelogicmaster_switchgdx_SwitchApplication_dispose(nullptr);
        exit(0);
    }
    eglSwapBuffers(display, surface);
}

